cd /c/zyh/work/ida_tmp && python - <<'EOF'
from elftools.elf.elffile import ELFFile
e=ELFFile(open('unitreeWebRTCClientMaster','rb'))
secs=[(s['sh_addr'],s.data()) for s in e.iter_sections() if s['sh_flags']&4 and s['sh_size']>0]
targets={
 0x132c20:'msg_incoming',0x132bb8:'errtable_count',0x132ca0:'incoming_topic',0x132cd8:'Req_type',
 0x132cf8:'Request_type',0x132d20:'Request_id',0x132d48:'ident_id',0x132d80:'subscribe',
 0x132dd0:'heartbeat',0x132ae8:'charset62',0x132b78:'validation',0x132b88:'validation_ok',
 0x132fe8:'validation_needed',0x133018:'invalid_topic',0x133048:'no_binary',0x133080:'parse_fail',
 0x132e620 if False else 0x132620:'sk_is_null',0x12cbf8:'rt/webrtcreq',0x12cc08:'rt/xfk_webrtcreq',
 0x132848:'hdl_1001_enter',0x132980:'hdl_1002_enter',0x132ab8:'invalid_api_id',
 0x1330d0:'validation_fmt',0x12e620:'sk_null',0x12cd90:'offerReceived_len',0x12cec0:'offer_check_passed',
 0x12cd08:'miss_offer_token',0x12cd48:'after_token',0x1322c8:'rt/api/pet/request',0x1318f8:'parameter',
 0x1324a0:'map_data_path',0x1327e8:'recv_pushed_unknown',0x132730:'err_open_write',0x1325b8:'send_static_param_null'
}
found={}
def page(a): return a & ~0xfff
for base,data in secs:
    for i in range(0,len(data)-8,4):
        insn=int.from_bytes(data[i:i+4],'little')
        if (insn & 0x9f000000)==0x90000000:
            rd=insn&0x1f
            imm=((insn>>5)&0x3ffff)<<2 | ((insn>>29)&3)
            if imm & (1<<20): imm-=(1<<21)
            tgt=page(base+i)+(imm<<12)
            if tgt in (page(t) for t in targets):
                for j in range(i+4,min(i+24,len(data)-4),4):
                    i2=int.from_bytes(data[j:j+4],'little')
                    if (i2 & 0xffc00000)==0x91000000 and (i2>>5)&0x1f==rd:
                        imm12=(i2>>10)&0xfff
                        if (i2>>22)&3==1: imm12<<=12
                        fa=tgt+imm12
                        if fa in targets:
                            found.setdefault(targets[fa],[]).append(hex(base+i))
                        break
for k,v in sorted(found.items()):
    print(k, v[:6])
EOF

