from elftools.elf.elffile import ELFFile
e=ELFFile(open('unitreeWebRTCClientMaster','rb'))
secs=[(s['sh_addr'],s.data()) for s in e.iter_sections() if s['sh_flags']&4 and s['sh_size']>0]
def page(a): return a & ~0xfff
raw=open('unitreeWebRTCClientMaster','rb').read()
def s(off):
    end=raw.find(b'\0',off)
    return raw[off:end][:60].decode('ascii','replace')
res=[]
for base,data in secs:
    n=len(data)
    for i in range(0,n-8,4):
        insn=int.from_bytes(data[i:i+4],'little')
        if (insn & 0x9f000000)==0x90000000:
            rd=insn&0x1f
            imm=((insn>>5)&0x3ffff)<<2 | ((insn>>29)&3)
            if imm & (1<<20): imm-=(1<<21)
            tgt=page(base+i)+(imm<<12)
            if tgt==0x133000:
                for j in range(i+4,min(i+48,n-4),4):
                    i2=int.from_bytes(data[j:j+4],'little')
                    if (i2 & 0xffc00000)==0x91000000 and (i2>>5)&0x1f==rd:
                        imm12=(i2>>10)&0xfff
                        if (i2>>22)&3==1: imm12<<=12
                        fa=tgt+imm12
                        if fa>=0x133d80:
                            res.append((base+i,fa))
                        break
for a,t in sorted(res): print(hex(a),hex(t),s(t))
EOF

